<script lang="ts">import{DirectPrintRoute}from'../print/direct.js';import{WebBluetoothTransport,WebSerialTransport,WebUsbTransport}from'../print/browser-transports.js';import{JobJournal}from'../jobs.js';import type{EditorDatabase}from'../persistence/database.js';import type{LabelDocument}from'../model.js';import type{PrinterDefinition,PrinterSdk,PrintRoute}from'../print/types.js';export let sdk:PrinterSdk;export let document:LabelDocument;export let printer:PrinterDefinition|undefined;export let database:EditorDatabase;export let onRoute:(route:PrintRoute)=>void=()=>{};let route:'bluetooth'|'spp'|'usb'='bluetooth';let service='0000ff00-0000-1000-8000-00805f9b34fb';let write='0000ff02-0000-1000-8000-00805f9b34fb';let notify='0000ff01-0000-1000-8000-00805f9b34fb';let vendorId='0x04f9';let productId='0x20a8';let status='';let active:DirectPrintRoute|undefined;let cancellation:AbortController|undefined;
function configure(){const journal=new JobJournal(database);if(route==='bluetooth')active=new DirectPrintRoute(sdk,async()=>new WebBluetoothTransport({service,writeCharacteristic:write,notifyCharacteristic:notify,physicalWriteLimit:20}),'bluetooth',()=>!!(navigator as Navigator&{bluetooth?:unknown}).bluetooth,journal);else if(route==='spp')active=new DirectPrintRoute(sdk,async()=>new WebSerialTransport({physicalWriteLimit:512,unfiltered:true}),'serial',()=>!!(navigator as Navigator&{serial?:unknown}).serial,journal);else active=new DirectPrintRoute(sdk,async()=>new WebUsbTransport({filters:[{vendorId:Number(vendorId),productId:Number(productId)}],interfaceNumber:0}),'usb',()=>!!(navigator as Navigator&{usb?:unknown}).usb,journal);onRoute(active);status=`${active.label} selected for direct, batch, and La Poste printing.`}
async function print(){if(!printer){status='Select a printer model first.';return}if(!active)configure();cancellation=new AbortController();status='Choose a device in the browser prompt…';const result=await active!.print({document,printer,copies:1,signal:cancellation.signal,onProgress:p=>status=`${p.phase}: ${p.bytesSent}/${p.totalBytes} bytes`});cancellation=undefined;status=result.outcome==='completed'?'Direct print completed.':`${result.outcome}: ${result.error??'Do not retry until the physical printer is checked.'}`;if(result.outcome==='failed'||result.outcome==='cancelled-before-send')active=undefined}
</script>
<section><h2>Direct browser print</h2><label>Route<select bind:value={route} on:change={()=>active=undefined}><option value="bluetooth">Web Bluetooth (BLE)</option><option value="spp">Bluetooth SPP (Web Serial)</option><option value="usb">WebUSB</option></select></label>{#if route==='bluetooth'}<details><summary>Bluetooth definition</summary><label>Service UUID<input bind:value={service}></label><label>Write UUID<input bind:value={write}></label><label>Notify UUID<input bind:value={notify}></label></details>{:else if route==='spp'}<p class="hint">Pair the printer first. On macOS choose the mapped QL serial port (cu.QL-1110NWB…), not the direct Bluetooth entry.</p>{:else}<label>USB vendor ID<input bind:value={vendorId}></label><label>USB product ID<input bind:value={productId}></label>{/if}<button on:click={configure}>Use for all print workflows</button><button on:click={print} disabled={!!cancellation}>Choose device & print current label</button>{#if cancellation}<button on:click={()=>cancellation?.abort()}>Cancel current job</button>{/if}<p aria-live="polite">{status}</p></section><style>section{padding:.75rem;border-top:1px solid var(--mble-border,#ddd)}h2{font-size:.8rem;text-transform:uppercase}label{display:flex;flex-direction:column;font-size:.75rem}.hint{font-size:.75rem;color:var(--mble-text-muted,#59635e)}</style>
